  for(const [path,contractPath,client,expected] of [['/requests','/requests',parent,requests],['/notes','/notes',parent,notes],[`/admin/accounts/${ids.guardian}/linkage`,'/admin/accounts/{id}/linkage',operator,children]] as const){const seen=await historyPages(client,path,contractPath);assert.equal(new Set(seen).size,seen.length);assert.deepEqual(seen.filter(x=>expected.includes(x)).sort(),[...expected].sort());for(const limit of ['0','51','1.5'])assert.equal((await client.call(path+'?limit='+limit)).status,400);}
