test('explicit teacher scopes bind subjects to the same stage, board, class or course/year in public search before pagination',async()=>{
 const main=await coveredTeacher(),crossed=await coveredTeacher([{stage:'SCHOOL',subject:'Physics',grade:11,board:'CBSE'},{stage:'SCHOOL',subject:'Chemistry',grade:12,board:'CBSE'}] as any,'A Synthetic crossed teacher');
 for(const t of [main.teacher,crossed.teacher])await db.teacher.update({where:{id:t.id},data:{status:'APPROVED',screeningComplete:true,screeningValidUntil:new Date(Date.now()+86400000)}});
 const search=async(q:string)=>(await new Client().call('/teachers?'+q)).data.items;
 const physics=await search('stage=SCHOOL&grade=12&board=cbse&subject=physics&limit=1');assert.deepEqual(physics.map((t:any)=>t.id),[main.teacher.id]);assert(operationValidator('/teachers','get','200')({items:physics,nextCursor:null}));
 assert((await search('stage=EARLY_YEARS&level=KG1&subject=language')).some((t:any)=>t.id===main.teacher.id));assert(!(await search('stage=EARLY_YEARS&level=KG2&subject=Language')).some((t:any)=>t.id===main.teacher.id));
 assert((await search('stage=COLLEGE&courseName=bsc%20physics&studyYear=2&subject=MECHANICS')).some((t:any)=>t.id===main.teacher.id));assert(!(await search('stage=COLLEGE&courseName=BA%20Economics&studyYear=1&subject=Mechanics')).some((t:any)=>t.id===main.teacher.id));assert(!(await search('stage=COLLEGE&courseName=BSc%20Physics&studyYear=3&subject=Mechanics')).some((t:any)=>t.id===main.teacher.id));assert((await search('q=mechanics')).some((t:any)=>t.id===main.teacher.id));
 assert.equal((await new Client().call('/teachers?stage=COLLEGE&grade=8')).status,400);assert.equal((await new Client().call('/teachers?grade=13')).status,400);
 await db.teacher.update({where:{id:main.teacher.id},data:{status:'SUSPENDED'}});assert(!(await search('stage=COLLEGE&subject=Mechanics')).some((t:any)=>t.id===main.teacher.id));
});
test('screening requires every explicit scope and resubmission withdraws expanded discovery until reviewed again',async()=>{
 const {client,body,teacher:t}=await coveredTeacher(),reviewer=await login(ids.admin),validUntil=new Date(Date.now()+30*86400000).toISOString();let version=1;
 for(const kind of ['IDENTITY','QUALIFICATIONS','CAPABILITY','REFERENCES']){
  const evidence=await db.evidence.create({data:{teacherId:t.id,kind,mediaType:'application/pdf',size:20,sha256:'a'.repeat(64),status:'CLEAN',scannerVersion:'synthetic-scanner',scannedAt:new Date()}}),input={expectedVersion:version,kind,evidenceId:evidence.id,result:'PASSED',reason:'Synthetic assessment of declared scopes',validUntil,...(kind==='CAPABILITY'?{coverage:{subjects:t.subjects,boards:t.boards,grades:t.grades,teachingCoverage:t.teachingCoverage}}:{})};
  if(kind==='CAPABILITY'){assert.equal((await reviewer.call('/admin/teachers/'+t.id+'/checks',{...input,coverage:{subjects:t.subjects,boards:t.boards,grades:t.grades}})).status,400);assert.equal((await reviewer.call('/admin/teachers/'+t.id+'/checks',{...input,coverage:{...input.coverage,teachingCoverage:t.teachingCoverage.slice(0,1)}})).status,400);}
  const checked=await reviewer.call('/admin/teachers/'+t.id+'/checks',input);assert.equal(checked.status,201,JSON.stringify(checked.data));version++;
 }
 const approved=await reviewer.call('/admin/teachers/'+t.id+'/reviews',{expectedVersion:version,status:'APPROVED',reason:'Synthetic checks cover every declared stage and curriculum'});assert.equal(approved.status,201,JSON.stringify(approved.data));assert.equal((await new Client().call('/teachers/'+t.slug)).status,200);
 const revised=await client.call('/teacher-applications/'+t.id+'/revisions',{...body,expectedVersion:approved.data.version,teachingCoverage:[...expandedScopes,{stage:'COLLEGE',subject:'Mechanics',courseName:'BSc Physics',studyYear:3}]});assert.equal(revised.status,201);assert.equal(revised.data.screeningComplete,false);assert.equal((await new Client().call('/teachers/'+t.slug)).status,404);assert.equal((await reviewer.call('/admin/teachers/'+t.id+'/reviews',{expectedVersion:revised.data.version,status:'APPROVED',reason:'Old checks must not cover new year'})).status,409);
});
