 assert.equal((await a.client.call('/admin/staff/changes',{...body,disabled:false})).status,400);assert.equal((await a.client.call('/admin/staff/changes',{...body,region:'UNREGISTERED'})).status,400);
 assert.equal((await a.client.call('/admin/staff/changes',{...body,email:'invalid-email'})).status,400);
