test('staff suspension, rejection and last-administrator protections preserve separation of duties',async()=>{
 const a=await staffAdmin('suspend proposer'),b=await staffAdmin('suspend approver'),target=await staffAdmin('suspend target');
 const proposal=await a.client.call('/admin/staff/changes',staffProposal({kind:'SUSPEND',email:undefined,name:undefined,role:undefined,region:undefined,targetAccountId:target.account.id,expectedAuthVersion:0}));assert.equal(proposal.status,201);assert.equal((await b.client.call(`/admin/staff/changes/${proposal.data.id}/decision`,staffDecision())).status,201);assert.equal((await target.client.call('/auth/session')).status,401);assert.equal((await db.account.findUniqueOrThrow({where:{id:target.account.id}})).disabled,true);
 const reject=await a.client.call('/admin/staff/changes',staffProposal());assert.equal((await b.client.call(`/admin/staff/changes/${reject.data.id}/decision`,staffDecision({decision:'REJECT'}))).data.status,'REJECTED');assert.equal(await db.account.count({where:{email:reject.data.email}}),0);
 const others=await db.account.findMany({where:{role:'ADMIN',disabled:false,id:{notIn:[a.account.id,b.account.id]}}});try{await db.account.updateMany({where:{id:{in:others.map(x=>x.id)}},data:{disabled:true}});const last=await a.client.call('/admin/staff/changes',staffProposal({kind:'SUSPEND',email:undefined,name:undefined,role:undefined,region:undefined,targetAccountId:b.account.id,expectedAuthVersion:0}));assert.equal(last.status,201);
 // A target cannot approve its own suspension; a third prior proposal cannot remove a protected quorum either.
 assert.equal((await b.client.call(`/admin/staff/changes/${last.data.id}/decision`,staffDecision())).status,403);
 }finally{await db.account.updateMany({where:{id:{in:others.map(x=>x.id)}},data:{disabled:false}});}
});
