test('managed-key rewrap drill preserves credentials, rejects retired keys and audits without key material',async()=>{
 const dir=mkdtempSync(path.join(tmpdir(),'bcs-b2-rewrap-')),file=path.join(dir,'ring.json'),rows=await db.mfaCredential.findMany(),next=randomBytes(32).toString('base64'),env={...process.env,DATABASE_URL:base.href,MIGRATION_DATABASE_URL:base.href,MFA_KEYRING_FILE:file,STAFF_SECURITY_REVIEW_REF:'drill:synthetic-key-rotation',STAFF_SECURITY_ACTOR_ID:ids.admin};
 try{writeFileSync(file,JSON.stringify({activeId:'next',legacyKeyId:'old',keys:{old:process.env.MFA_ENCRYPTION_KEY,next}}),{mode:0o600});const run=spawnSync(process.execPath,['--import','tsx','scripts/staff-security.ts','rewrap'],{env,encoding:'utf8'});assert.equal(run.status,0,run.stderr);assert(!run.stdout.includes(next));assert.equal(JSON.parse(run.stdout).count,rows.length);const saved=await db.mfaCredential.findMany();assert(saved.every(x=>x.encryptedSecret.startsWith('v1:next:')));process.env.MFA_KEYRING_FILE=file;for(const row of saved)assert.match(decryptMfa(row.encryptedSecret,row.accountId),/^[A-Z2-7]{32}$/);delete process.env.MFA_KEYRING_FILE;
 writeFileSync(file,JSON.stringify({activeId:'wrong',keys:{wrong:randomBytes(32).toString('base64')}}));const fail=spawnSync(process.execPath,['--import','tsx','scripts/staff-security.ts','rewrap'],{env,encoding:'utf8'});assert.notEqual(fail.status,0);assert.deepEqual((await db.mfaCredential.findMany({orderBy:{accountId:'asc'}})).map(x=>x.encryptedSecret),saved.sort((a,b)=>a.accountId.localeCompare(b.accountId)).map(x=>x.encryptedSecret));assert.equal(await db.audit.count({where:{action:'MFA_KEYS_REWRAPPED',reason:'drill:synthetic-key-rotation'}}),1);
 }finally{delete process.env.MFA_KEYRING_FILE;for(const row of rows)await db.mfaCredential.update({where:{accountId:row.accountId},data:{encryptedSecret:row.encryptedSecret}});rmSync(dir,{recursive:true});}
});
test('initial staff bootstrap is atomic, requires two reviewers and cannot bypass an existing installation',async()=>{
 const database='bcs_bootstrap_'+randomUUID().replace(/-/g,''),url=new URL(base);url.pathname='/'+database;const dir=mkdtempSync(path.join(tmpdir(),'bcs-bootstrap-')),ring=path.join(dir,'ring.json'),file=path.join(dir,'staff.json');let target:Pool|undefined;
 try{await admin.query(`CREATE DATABASE "${database}"`);const env={...process.env,DATABASE_URL:url.href,MIGRATION_DATABASE_URL:url.href,MFA_KEYRING_FILE:ring,STAFF_SECURITY_REVIEW_REF:'drill:initial-staff',STAFF_BOOTSTRAP_CONFIRM:'INITIAL_THREE_ADMINS_NO_EXISTING_STAFF'};execFileSync(process.execPath,['node_modules/prisma/build/index.js','migrate','deploy'],{env,stdio:'pipe'});writeFileSync(ring,JSON.stringify({activeId:'initial',keys:{initial:randomBytes(32).toString('base64')}}),{mode:0o600});const input={reviewers:['reviewer-one','reviewer-two'],admins:[1,2,3].map(i=>({email:`staff${i}@example.test`,name:'Synthetic initial admin '+i,region:'Raipur'}))};writeFileSync(file,JSON.stringify({...input,reviewers:['same','same']}),{mode:0o600});const run=()=>spawnSync(process.execPath,['--import','tsx','scripts/staff-security.ts','bootstrap',file],{env,encoding:'utf8'});assert.notEqual(run().status,0);target=new Pool({connectionString:url.href});assert.equal(Number((await target.query('SELECT count(*) FROM "Account"')).rows[0].count),0);writeFileSync(file,JSON.stringify(input));const result=run();assert.equal(result.status,0,result.stderr);assert.equal(Number((await target.query('SELECT count(*) FROM "Account" WHERE role=\'ADMIN\'')).rows[0].count),3);assert.equal(Number((await target.query('SELECT count(*) FROM "Audit" WHERE action=\'STAFF_INITIAL_BOOTSTRAP\'')).rows[0].count),1);assert.notEqual(run().status,0);assert.equal(Number((await target.query('SELECT count(*) FROM "Account"')).rows[0].count),3);
 }finally{await target?.end();await admin.query(`DROP DATABASE IF EXISTS "${database}" WITH (FORCE)`);rmSync(dir,{recursive:true});}
});
test('staff recovery serializes against already-authorized MFA requests and rejects stale enrollment after revocation',async()=>{
 const a=await staffAdmin('serialization proposer'),b=await staffAdmin('serialization reviewer'),target=await staffAdmin('serialization target'),pool=new Pool({connectionString:base.href}),lock=await pool.connect();
 const proposed=await a.client.call('/admin/staff/changes',staffProposal({kind:'RECOVER',targetAccountId:target.account.id,expectedAuthVersion:0,email:undefined,name:undefined,role:undefined,region:undefined}));assert.equal(proposed.status,201);
 const key=target.account.id+':mfa';let approval:Promise<any>|undefined,enrollment:Promise<any>|undefined;
 async function waiting(count:number){for(let i=0;i<100;i++){const r=await pool.query("SELECT count(*) FROM pg_locks l JOIN pg_stat_activity a ON a.pid=l.pid WHERE a.datname=$1 AND l.locktype='advisory' AND NOT l.granted",[name]);if(Number(r.rows[0].count)>=count)return;await new Promise(r=>setTimeout(r,20));}assert.fail('Expected MFA advisory lock wait was not observed');}
 try{await lock.query('SELECT pg_advisory_lock(hashtextextended($1,0))',[key]);approval=b.client.call(`/admin/staff/changes/${proposed.data.id}/decision`,staffDecision());await waiting(1);enrollment=target.client.call('/auth/mfa/enrollment',{});await waiting(2);await lock.query('SELECT pg_advisory_unlock(hashtextextended($1,0))',[key]);const results=await Promise.all([approval,enrollment]);assert.deepEqual(results.map(r=>r.status),[201,401]);assert.equal(await db.mfaCredential.count({where:{accountId:target.account.id}}),0);const fresh=await login(target.account.id,false);assert.equal((await fresh.call('/auth/mfa/enrollment',{})).status,201);
 }finally{await lock.query('SELECT pg_advisory_unlock_all()');lock.release();await Promise.allSettled([approval,enrollment].filter(Boolean));await pool.end();}
});

const commercialReason={reason:'Reviewed pilot hiring policy change',evidenceRef:'policy:synthetic-commercial',confirmed:true};
async function commercialChange(a:Client,extra:any){const current=await a.call('/admin/commercial');assert.equal(current.status,200,JSON.stringify(current.data));return a.call('/admin/commercial/changes',{...commercialReason,expectedVersion:current.data.version,...extra});}
async function approveCommercial(b:Client,id:string){return b.call(`/admin/commercial/changes/${id}/decision`,staffDecision());}
async function resetCommercial(a:Client,b:Client){const p=await commercialChange(a,{kind:'ROLLBACK',restoreVersion:0});if(p.status===201)assert.equal((await approveCommercial(b,p.data.id)).status,201);else assert.equal(p.data.code,'NO_CHANGE');}
test('commercial changes require fresh ADMIN MFA, bounded inputs and independent approval with a single immutable revision',async()=>{
 const a=await staffAdmin('commercial proposer'),b=await staffAdmin('commercial reviewer');assert.equal((await parent.call('/admin/commercial')).status,403);const bare=await login(a.account.id,false);assert.equal((await bare.call('/admin/commercial')).status,403);
 const current=await a.client.call('/admin/commercial');assert.equal(current.status,200);assert.equal(current.data.chargesEnabled,false);const validate=operationValidator('/admin/commercial','get','200');assert(validate(current.data),JSON.stringify(validate.errors));
 for(const fee of [{placementBasisPoints:2501,placementCapPaise:150000},{placementBasisPoints:1.5,placementCapPaise:1000},{placementBasisPoints:1000,placementCapPaise:-1}])assert.equal((await a.client.call('/admin/commercial/changes',{...commercialReason,expectedVersion:current.data.version,kind:'FEE',fee})).status,400);
 const body={...commercialReason,expectedVersion:current.data.version,kind:'FEE',fee:{placementBasisPoints:2000,placementCapPaise:100000}},key=randomUUID(),p=await a.client.call('/admin/commercial/changes',body,{key});assert.equal(p.status,201,JSON.stringify(p.data));assert.equal((await a.client.call('/admin/commercial/changes',body,{key})).data.id,p.data.id);assert.equal((await a.client.call(`/admin/commercial/changes/${p.data.id}/decision`,staffDecision())).status,403);assert.equal((await db.commercialState.findUniqueOrThrow({where:{id:'hiring'}})).version,current.data.version);
 const approveKey=randomUUID(),r=await b.client.call(`/admin/commercial/changes/${p.data.id}/decision`,staffDecision(),{key:approveKey});assert.equal(r.status,201,JSON.stringify(r.data));assert.equal((await b.client.call(`/admin/commercial/changes/${p.data.id}/decision`,staffDecision(),{key:approveKey})).data.id,p.data.id);assert.equal(await db.commercialRevision.count({where:{changeId:p.data.id}}),1);assert.equal(await db.audit.count({where:{action:'COMMERCIAL_APPROVED',aggregateId:p.data.id}}),1);
 const state=await db.commercialState.findUniqueOrThrow({where:{id:'hiring'}});assert.equal(state.placementBasisPoints,2000);assert.equal(state.placementCapPaise,100000);const console=await a.client.call('/admin/console');assert.equal(console.data.commercial.placementExamples[0].feePaise,20000);
 await assert.rejects(()=>db.commercialRevision.update({where:{version:state.version},data:{reason:'tampered'}}));await resetCommercial(a.client,b.client);
});
