 const placement=await f.g.call('/placements',{requestId:request.data.id,teacherId:t.id});assert.equal(placement.status,201,JSON.stringify(placement.data));assert.equal(placement.data.placementFeePaise,20000);assert(placement.data.commercialVersion>0);await assert.rejects(()=>db.placement.update({where:{id:placement.data.id},data:{placementFeePaise:1}}));
 await resetCommercial(a.client,b.client);const summary=await f.g.call('/dashboard/hiring?section=ARRANGEMENTS');assert.equal(summary.data.arrangements[0].placementFeePaise,20000);assert.deepEqual((await fresh.c.call('/student-arrangements/'+fresh.arrangement.id)).data.terms,fresh.arrangement.terms);
