async function runGuardianEvidenceWorker(id:string,available=true){
 const pool=new Pool({connectionString:base.href}),lock=await pool.connect();
 try{await lock.query('BEGIN');await lock.query('SELECT id FROM "Outbox" WHERE "processedAt" IS NULL AND "aggregateId"<>$1 FOR UPDATE',[id]);runEvidenceWorker(available);}finally{await lock.query('ROLLBACK');lock.release();await pool.end();}
}
