const guardianReview=(extra={})=>({expectedVersion:1,decision:'APPROVE',reason:'Synthetic reviewed relationship',reviewReference:'protected-review/synthetic',adultAndAuthorityChecked:true,documentNameMatched:true,studentAcknowledgmentObserved:true,callMethod:'VIDEO',confirmed:true,...extra});
