 assert.equal((await review.call(`/admin/guardian-verifications/${id}/decisions`,guardianReview({expectedVersion:v.version}))).data.code,'STUDENT_ACKNOWLEDGMENT_REQUIRED');
 const invited=await s.client.call('/guardian-verification-invitations');assert.equal(invited.status,200);assert.equal(invited.data.items[0].managementMode,'SHARED');
 assert.equal((await other.call(`/guardian-verifications/${id}/student-acknowledgments`,{expectedVersion:v.version,confirmed:true})).status,404);
 const ack=await s.client.call(`/guardian-verifications/${id}/student-acknowledgments`,{expectedVersion:v.version,confirmed:true});assert.equal(ack.status,201);
 v=(await g.client.call('/guardian-verifications/'+id)).data;
 assert.equal((await review.call(`/admin/guardian-verifications/${id}/decisions`,guardianReview({expectedVersion:v.version,adultAndAuthorityChecked:false}))).status,409);
 const reviewKey=randomUUID(),decision=guardianReview({expectedVersion:v.version});const done=await review.call(`/admin/guardian-verifications/${id}/decisions`,decision,{key:reviewKey});assert.equal(done.status,201,JSON.stringify(done.data));assert.equal(done.data.status,'APPROVED');await assert.rejects(db.guardianVerification.update({where:{id},data:{guardianName:'Tampered guardian'}}));assert.equal((await review.call(`/admin/guardian-verifications/${id}/decisions`,decision,{key:reviewKey})).data.version,done.data.version);
