 async function waiting(minimum:number){for(let i=0;i<100;i++){const r=await pool.query("SELECT count(*) FROM pg_locks l JOIN pg_stat_activity a ON a.pid=l.pid WHERE a.datname=$1 AND l.locktype='advisory' AND NOT l.granted",[name]);if(Number(r.rows[0].count)>=minimum)return;await new Promise(r=>setTimeout(r,20));}assert.fail('Expected queued authority transactions');}
 try{await lock.query('SELECT pg_advisory_lock(hashtextextended($1,0))',[f.owner.id]);change=f.g.call(`/children/${id}/learning-management`,learningMode('GUARDIAN_ONLY',2));await waiting(1);write=f.s.call('/requests',learningIntake(f.linkedChild));await waiting(2);await lock.query('SELECT pg_advisory_unlock_all()');assert.equal((await change).status,201);assert.equal((await write).status,403);assert.equal(await db.tuitionRequest.count({where:{childId:id}}),0);
 }finally{await lock.query('SELECT pg_advisory_unlock_all()');lock.release();if(change)await change;if(write)await write;await pool.end();}
