async function mailEnvironment<T>(fn:(email:typeof import('../packages/email/index.cjs'))=>Promise<T>){const names=['APP_MODE','NODE_ENV','EMAIL_DELIVERY_MODE','RESEND_API_KEY','EMAIL_FROM','EMAIL_CONTENT_KEY','PUBLIC_APP_URL'],old=Object.fromEntries(names.map(n=>[n,process.env[n]]));try{Object.assign(process.env,{APP_MODE:'development',NODE_ENV:'test',EMAIL_DELIVERY_MODE:'resend',RESEND_API_KEY:'synthetic-provider-key',EMAIL_FROM:'synthetic@example.test',EMAIL_CONTENT_KEY:randomBytes(32).toString('base64'),PUBLIC_APP_URL:'http://localhost:3000'});return await fn(await import('../packages/email/index.cjs'));}finally{for(const n of names)if(old[n]===undefined)delete process.env[n];else process.env[n]=old[n];}}
