function emailReceiptSignature(eventId:string,raw:string,offset=0){const timestamp=String(Math.floor(Date.now()/1000)+offset),signature=createHmac('sha256',Buffer.from(process.env.EMAIL_WEBHOOK_SECRET!.slice(6),'base64')).update(eventId+'.'+timestamp+'.'+raw).digest('base64');return {'svix-id':eventId,'svix-timestamp':timestamp,'svix-signature':'v1,'+signature};}
async function postReceipt(eventId:string,body:unknown,offset=0){const raw=JSON.stringify(body),response=await fetch('http://127.0.0.1:4100/api/v1/notifications/webhooks/resend',{method:'POST',headers:{'Content-Type':'application/json',...emailReceiptSignature(eventId,raw,offset)},body:raw});return {status:response.status,data:await response.json()};}
