test('Socket.IO authenticates the current recipient and rejects forged CSRF and origins',async()=>{const {io}=await import('socket.io-client'),f=await educationActors();const connect=(auth:any,origin='http://localhost:3000')=>io('http://127.0.0.1:4100',{path:'/api/v1/live',transports:['polling'],auth,extraHeaders:{Cookie:f.g.cookies,Origin:origin},reconnection:false,timeout:3000});const good=connect({csrfToken:f.g.csrf});try{await new Promise<void>((resolve,reject)=>{good.once('inbox:changed',()=>resolve());good.once('connect_error',reject);setTimeout(()=>reject(Error('Missing live update')),4000).unref();});const changed=new Promise<void>((resolve,reject)=>{good.once('inbox:changed',()=>resolve());setTimeout(()=>reject(Error('Missing new notification signal')),5000).unref();});const r=await f.g.call('/requests',{...intake({childId:f.linkedChild.id}),alias:f.linkedChild.alias,schoolName:f.linkedChild.schoolName!,schoolSubjects:f.linkedChild.schoolSubjects});assert.equal(r.status,201);await changed;const disconnected=new Promise<void>((resolve,reject)=>{good.once('disconnect',()=>resolve());setTimeout(()=>reject(Error('Revoked session stayed connected')),5000).unref();});await db.session.updateMany({where:{accountId:f.owner.id},data:{revoked:true}});await disconnected;}finally{good.disconnect();}const again=await dashboardLogin(f.owner.id);f.g.cookies=again.cookies;f.g.csrf=again.csrf;for(const [csrf,origin]of [['wrong','http://localhost:3000'],[f.g.csrf,'https://foreign.invalid']]){const bad=connect({csrfToken:csrf},origin);try{await new Promise<void>((resolve,reject)=>{bad.once('connect',()=>reject(Error('Unauthorized socket connected')));bad.once('connect_error',()=>resolve());});}finally{bad.disconnect();}}});
